/* Herramienta de Consultas en Vivo - Versión Optimizada */
let fetch;
try {
    fetch = global.fetch || require('node-fetch');
} catch (e) {
    console.log("Error al cargar fetch, intentando usar global...");
    fetch = global.fetch;
}

// Usamos el nombre del servicio 'n8n' para comunicación interna en Docker
const webhookUrl = "http://n8n:5678/webhook/ejecutar-fleet";

const options = {
    method: 'POST',
    headers: {
        'Content-Type': 'application/json'
    },
    body: JSON.stringify({ 
        query: $query, 
        action: "live_query" 
    })
};

try {
    const response = await fetch(webhookUrl, options);

    if (response.ok) {
        const data = await response.text();
        // Limitamos la salida para no saturar los tokens de la IA
        const dataSegura = data.length > 3000 ?
            data.substring(0, 3000) + "... [DATOS TRUNCADOS]" :
            data;
        return "Resultado de Fleet: " + dataSegura;
    } else {
        const errorText = await response.text();
        return `Error en n8n: ${response.status} - ${errorText}`;
    }
} catch (error) {
    return `Error técnico de conexión: ${error.message}. Asegúrate de que el contenedor de n8n esté activo.`;
}
